labeled_query:
SELECT ?country ?countryLabel (AVG(?lifespan) AS ?avgLifespan) WHERE {
  ?person wdt:[property:country of citizenship] ?country .
  ?person wdt:[property:date of birth] ?birth .
  ?person wdt:[property:date of death] ?death .
  BIND((YEAR(?death) - YEAR(?birth)) AS ?lifespan)
  FILTER(?lifespan > 0 && ?lifespan < 150)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?avgLifespan)

linked_query:
SELECT ?country ?countryLabel (AVG(?lifespan) AS ?avgLifespan) WHERE {
  ?person wdt:P27 ?country .
  ?person wdt:P569 ?birth .
  ?person wdt:P570 ?death .
  BIND((YEAR(?death) - YEAR(?birth)) AS ?lifespan)
  FILTER(?lifespan > 0 && ?lifespan < 150)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?avgLifespan)

